<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o)go('index.php');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$status=$_POST['status']??'new';$allowed=['new','confirmed','processing','shipped','completed','cancelled'];if(in_array($status,$allowed,true)){db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$status,$id]);}$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();}$q=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$id]);$items=$q->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الطلب <?=h($o['order_number'])?></title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>طلب <?=h($o['order_number'])?></h1><p><?=h($o['customer_name'])?> - <?=h($o['phone'])?></p><p><?=h($o['city'])?> - <?=h($o['address'])?></p><div class="table-wrap"><table><tr><th>المنتج</th><th>الكمية</th><th>السعر</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['product_name'])?></td><td><?=$i['quantity']?></td><td><?=money($i['line_total'])?></td></tr><?php endforeach?></table></div><h2>الإجمالي <?=money($o['total'])?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><select name="status"><?php foreach(['new','confirmed','processing','shipped','completed','cancelled'] as $v):?><option value="<?=$v?>" <?=$o['status']===$v?'selected':''?>><?=$v?></option><?php endforeach?></select><button class="gold">تحديث الحالة</button></form></main></body></html>